# Section navigation: parse markdown-style headings into a tree, jump to a section.
doc = """# Report\nIntro text\n## Methods\nWe measured twice.\n## Results\nIt worked.""".replace("\\n", "\n")
def parse(lines):
    root = {"title": "ROOT", "level": 0, "children": [], "body": []}
    stack = [root]
    for line in lines:
        if line.startswith("#"):
            level = len(line) - len(line.lstrip("#"))
            node = {"title": line.strip("# ").strip(), "level": level, "children": [], "body": []}
            while stack[-1]["level"] >= level: stack.pop()
            stack[-1]["children"].append(node); stack.append(node)
        else:
            stack[-1]["body"].append(line)
    return root
def find(node, title):
    if node["title"].lower() == title.lower(): return node
    for c in node["children"]:
        r = find(c, title)
        if r: return r
    return None
def outline(node, depth=0):
    for c in node["children"]:
        print("  "*depth + "- " + c["title"]); outline(c, depth+1)
root = parse(doc.splitlines())
print("Outline:"); outline(root)
target = "Methods"
node = find(root, target)
print(f"\nJump to '{target}':")
print("\n".join(node["body"]).strip() if node else "not found")

